import{z as s,x as i,o as A,c as p,q as r,j as l,D as e,d as B,s as o,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"零拷贝与延迟测量","description":"","frontmatter":{"title":"零拷贝与延迟测量","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hpc-zerocopy-latency.md","filePath":"cs/hpc-zerocopy-latency.md","lastUpdated":1791413859000}'),d={name:"cs/hpc-zerocopy-latency.md"};function C(P,E,c,m,F,D){const t=i("Mermaid");return A(),p("div",null,[E[2]||(E[2]=r('<h1 id="零拷贝与延迟测量" tabindex="-1">零拷贝与延迟测量 <a class="header-anchor" href="#零拷贝与延迟测量" aria-label="Permalink to &quot;零拷贝与延迟测量&quot;">​</a></h1><div class="epigraph"><p>省一次拷贝省的是几百纳秒；时间戳打错一个位置，结论能假出一个数量级。</p><footer>—— 据 Linux `timestamping` 文档与 IEEE 1588（PTP）整理</footer></div><p><a href="/cs/hpc-rdma">上一课</a>把跨机路径压进网卡，前提是专用网络与注册内存；多数服务仍在通用栈上，能省的是拷贝，能信的是测量。<a href="/cs/zero-copy-network">零拷贝网络</a>已在主干钉了拷贝的来源与 sendfile、MSG_ZEROCOPY、AF_XDP 三个接头；本课不重复词条，写两件事：通用发送路径上零拷贝的真实取舍，以及省下来的时间如何被诚实地量出来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>零拷贝在发送方向收益明确，接收方向困难。发送可以把用户页直接挂进发送路径：MSG_ZEROCOPY 免掉缓冲到 skb 的拷贝，但页在网卡完成前不能复用，完成通知走异常队列，应用必须专门收割——忘了收割就是页泄漏。小包更微妙：内核对小于阈值的包直接拷贝，因为管理页引用的元数据开销超过拷贝本身，「零拷贝一定更快」在小包高频场景是反的。</p><p><span class="marginnote">常见误区：初学者容易以为零拷贝处处更快。实际上内核对小包（阈值随平台与 MTU 变动，常见 KB 量级）直接拷贝反而便宜——为省几十纳秒的拷贝去管理页引用的元数据账，是捡了芝麻丢了西瓜。大包（如几十 KB 的文件块）才是 MSG_ZEROCOPY 的主场。</span>测量侧的坑一串：跨机用系统时钟相减，钟差就有几十微秒；批量压测把排队延迟摊进平均值，报出的「平均延迟」掩盖尾部；中位数漂亮而 p99 爆炸的分布比比皆是。不这么做会错在哪：优化前后用不同位置的软件时间戳相减，得到的提升可能只是打点位置变了。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>打点分三层：NIC 硬件时间戳最接近线缆（SO_TIMESTAMPING 请求），驱动打点次之，纯软件打点含协议栈噪声。跨机对钟用 PTP（IEEE 1588），并把残余同步误差一并报出。指标报分布不报均值：p50、p99、p99.9 与最大值，注明采样窗口与负载形态；吞吐与延迟分开测，<a href="/cs/network-measurement">ping / iperf</a> 给的是基线口径，负载上升时排队延迟与利用率同向增长，两条曲线不能混。对照实验钉死变量：同一打点位置、同一批大小、关掉 Nagle（TCP_NODELAY）与中断聚合这类会移动分布的旋钮再比较。</p>',8)),(A(),l(n,null,{default:e(()=>[o(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%E7%BC%93%E5%86%B2%22%5D%20--%3E%20ZC%7B%22%E5%8F%91%E9%80%81%E8%B7%AF%E5%BE%84%E9%80%89%E6%8B%A9%22%7D%0A%20%20ZC%20--%3E%7CMSG_ZEROCOPY%7C%20PIN%5B%22%E7%94%A8%E6%88%B7%E9%A1%B5%E6%8C%82%E8%BF%9B%20skb%EF%BC%8C%E5%AE%8C%E6%88%90%E5%90%8E%E5%9B%9E%E6%94%B6%22%5D%0A%20%20ZC%20--%3E%7Cwrite%7C%20SKB%5B%22%E6%8B%B7%E8%B4%9D%E8%BF%9B%E5%A5%97%E6%8E%A5%E5%AD%97%E7%BC%93%E5%86%B2%22%5D%0A%20%20PIN%20--%3E%20NIC%5B%22NIC%EF%BC%9ADMA%20%E4%B8%8E%E7%A1%AC%E4%BB%B6%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A%20%20SKB%20--%3E%20NIC%0A%20%20NIC%20--%3E%20WIRE%5B%22%E7%BA%BF%E7%BC%86%22%5D%0A%20%20WIRE%20--%3E%20PEER%5B%22%E5%AF%B9%E7%AB%AF%EF%BC%9APTP%20%E5%AF%B9%E9%92%9F%E5%90%8E%E5%8F%AF%E6%AF%94%22%5D%0A%20%20PEER%20--%3E%20STATS%5B%22%E6%8A%A5%20p50%20%2F%20p99%20%2F%20p99.9%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"测量的机制定义：延迟是因果链上两个事件的间隔，误差等于打点误差加打点位置到物理事件之间的剩余路径。硬件时间戳把打点推进到 MAC 层，剩余路径最短；软件时间戳含调度与软中断噪声。所以延迟数字必须连打点位置一起报，否则数字没有语义。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：报延迟不报打点位置，就像报跑步成绩不说从哪里起跑——NIC 硬件时间戳是「从发令枪起跑」，应用层软件时间戳则把排队、唤醒全算进了成绩。同一段路，两种报法能差出一个数量级。"),B("零拷贝的机制账：省的是拷贝与随之而来的缓存失效，付的是页管理、完成通知与代码复杂度；接收方向头解析仍要 CPU 碰数据，小包直接拷贝反而便宜，阈值随平台与 MTU 变动。分布形态本身也是信号：轮询的旁路路径窄而稳，中断路径常呈双峰——聚合窗口内与外的包延迟不同，均值会把两种机制搅成一台账。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"Nagle 算法与延迟确认叠加可引入约 40 ms 量级的假尖峰：小包被扣住等 ACK 才能发出。压测前先开 TCP_NODELAY 关掉 Nagle，再逐个打开其余旋钮归因。")],-1)),E[7]||(E[7]=a("p",null,"同一个物理事件，在不同打点位置读出的延迟为什么差一个量级？把三层打点的剩余路径摊开：",-1)),(A(),l(n,null,{default:e(()=>[o(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20EV%5B%22%E7%89%A9%E7%90%86%E4%BA%8B%E4%BB%B6%EF%BC%9A%E5%B8%A7%E5%88%B0%E8%BE%BE%E7%BA%BF%E7%BC%86%22%5D%20--%3E%20HW%5B%22NIC%20%E7%A1%AC%E4%BB%B6%E6%97%B6%E9%97%B4%E6%88%B3%EF%BC%9A%E5%89%A9%E4%BD%99%E8%B7%AF%E5%BE%84%E6%9C%80%E7%9F%AD%22%5D%0A%20%20HW%20--%3E%20DRV%5B%22%E9%A9%B1%E5%8A%A8%E6%89%93%E7%82%B9%EF%BC%9A%E5%8F%A0%E5%8A%A0%E4%B8%AD%E6%96%AD%E4%B8%8E%E8%B0%83%E5%BA%A6%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20DRV%20--%3E%20SW%5B%22%E8%BD%AF%E4%BB%B6%E6%97%B6%E9%97%B4%E6%88%B3%EF%BC%9A%E5%8F%A0%E5%8A%A0%E8%BD%AF%E4%B8%AD%E6%96%AD%E4%B8%8E%E5%8D%8F%E8%AE%AE%E6%A0%88%E5%99%AA%E5%A3%B0%22%5D%0A%20%20SW%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%E8%A7%82%E6%B5%8B%E7%82%B9%EF%BC%9A%E5%86%8D%E5%8F%A0%E5%8A%A0%E6%8E%92%E9%98%9F%E4%B8%8E%E5%94%A4%E9%86%92%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 PTP 的报文与时钟伺服细节，不写硬件抓包仪；量化栏<a href="/quant/colocation-microwave">主机托管与微波</a>钉过「研究必须声明接入与介质」，本课的对应纪律是「结论必须声明打点位置」。下一课收束全课程。</p><p><span class="marginnote">数字实例：普通 NTP 对钟下，两台机器的时钟差可达几十微秒；而一次零拷贝省下的只有几百纳秒——测量误差比优化收益大两个量级，跨机相减的结论自然整个作废。PTP 能把残余误差压到亚微秒级，报数时要连残余误差一起报。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发送方向零拷贝收益明确但要管页生命周期；小包低于阈值时拷贝反而便宜。</li><li>延迟是因果链两事件之差；报数字必须同时报打点位置与残余时钟误差。</li><li>分布重于均值：p99/p99.9、负载形态、批量与排队效应一起报。</li><li>Nagle、中断聚合、批大小都会移动分布，对照实验要钉死这些旋钮。</li><li>出处：Linux <code>SO_TIMESTAMPING</code>/<code>timestamping</code> 文档；IEEE 1588；测量实践。</li></ul>',5))])}const u=s(d,[["render",C]]);export{h as __pageData,u as default};
